# Content and components for the supplied 33-page proposal.
def tr(l,sq,en,de): return {"sq":sq,"en":en,"de":de}[l]
PAGES=["index","services","projects","partners","creative","ai-agents","about","contact","krakenos"]
NAV_ORDER=['index','services','projects','partners','krakenos','creative','ai-agents','about','contact']
def labels(l): return tr(l,["Kreu","Shërbimet","Projektet","Partnerët","Kreativa","AI Agents","Rreth nesh","Kontakt","KrakenOS"],["Home","Services","Projects","Partners","Creative","AI Agents","About us","Contact","KrakenOS"],["Start","Leistungen","Projekte","Partner","Kreativ","KI-Agenten","Über uns","Kontakt","KrakenOS"])
def copy(l):
 return {
 "home":tr(l,"Teknologji që ta lehtëson punën.","Technology that makes work easier.","Technologie, die Ihre Arbeit erleichtert."),
 "homelead":tr(l,"Një partner për faqen, sistemet, sigurinë dhe idetë që duan të kthehen në punë reale.","One partner for your website, systems, security and ideas ready to become real work.","Ein Partner für Ihre Website, Systeme, Sicherheit und Ideen, die Wirklichkeit werden sollen."),
 "services":tr(l,"Çfarë do të rregullojmë sot?","What shall we improve today?","Was verbessern wir heute?"),
 "projects":tr(l,"Puna që mund ta shohësh.","Work you can see.","Arbeit, die sichtbar wird."),
 "partners":tr(l,"Me kë ndërtojmë zgjidhje më të forta.","The technologies behind stronger solutions.","Technologien für stärkere Lösungen."),
 "partnerlead":tr(l,"Platformat, mjetet dhe infrastruktura që lidhim me nevojën e projektit tënd.","Platforms, tools and infrastructure connected around your project’s needs.","Plattformen, Werkzeuge und Infrastruktur, passend zu Ihrem Projekt."),
 "about":tr(l,"Një ekip brenda rrjedhës suaj.","A team that fits the way you work.","Ein Team, das Ihre Abläufe versteht."),
 "contact":tr(l,"Nisemi nga ajo që të duhet.","Let’s start with what you need.","Beginnen wir mit Ihrem Bedarf."),
 "all":tr(l,"Të gjitha","All","Alle"),
 "families":tr(l,["Web & softuer","IT & siguri","AI Agents","Kreativa"],["Web & software","IT & security","AI Agents","Creative"],["Web & Software","IT & Sicherheit","KI-Agenten","Kreativ"]),
 "familydesc":tr(l,["Faqe, aplikacione dhe sisteme që lidhin punën.","Rrjete, siguri dhe mbështetje për çdo ditë.","Më pak detyra të përsëritura. Më shumë kontroll.","Identitet, përmbajtje dhe fushata që dallohen."],["Websites, applications and systems that connect your work.","Networks, security and support for the everyday.","Less repetitive work. More control.","Identity, content and campaigns that stand out."],["Websites, Anwendungen und Systeme für verbundene Abläufe.","Netzwerke, Sicherheit und Support im Alltag.","Weniger Routine. Mehr Kontrolle.","Identität, Inhalte und Kampagnen, die auffallen."]),
 "see":tr(l,"Shiko shërbimet","Explore services","Leistungen ansehen"),
 "book":tr(l,"Cakto takim","Book a meeting","Termin vereinbaren"),
 "details":tr(l,"Shiko detajet","Explore details","Details ansehen"),
 "request":tr(l,"Kërko një vlerësim","Discuss your project","Projekt besprechen"),
 "flow":tr(l,"Nga kërkesa te zgjidhja","From request to solution","Von der Anfrage zur Lösung"),
 "flowsteps":tr(l,["Kuptojmë","Ndërtojmë","Mbështesim"],["Understand","Build","Support"],["Verstehen","Entwickeln","Begleiten"]),
 "selected":tr(l,"Pak nga puna jonë.","A closer look at our work.","Ein Einblick in unsere Arbeit."),
 "casetitle":tr(l,"Proces më i qartë për ekipin.","A clearer process for the team.","Klarere Abläufe für das Team."),
 "casefull":tr(l,"Raporte dhe aprovime me më pak hapa.","Reports and approvals in fewer steps.","Berichte und Freigaben mit weniger Schritten."),
 "casebadge":tr(l,"Rast ilustrues · Softuer","Illustrative case · Software","Beispielszenario · Software"),
 "result":tr(l,"Rezultati i synuar","Intended result","Angestrebtes Ergebnis"),
 "stepnames":tr(l,["Kuptojmë","Planifikojmë","Realizojmë","Përmirësojmë"],["Understand","Plan","Deliver","Improve"],["Verstehen","Planen","Umsetzen","Verbessern"]),
 "stepdesc":tr(l,["Nisim nga ajo që të pengon sot.","Përcaktojmë rrugën, afatin dhe përgjegjësitë.","Ndërtojmë, provojmë dhe dorëzojmë.","Matim, mësojmë dhe qëndrojmë pranë."],["Start with what gets in your way today.","Agree on the scope, timing and responsibilities.","Build, test and hand over.","Measure, learn and stay close."],["Wir beginnen bei Ihren heutigen Hindernissen.","Umfang, Zeitplan und Verantwortung festlegen.","Entwickeln, prüfen und übergeben.","Messen, lernen und weiter begleiten."]),
 "company":tr(l,"Kompania","Company","Unternehmen"),
 "phone":tr(l,"Telefoni (opsional)","Phone (optional)","Telefon (optional)"),
 "send":tr(l,"Dërgo kërkesën","Send enquiry","Anfrage senden"),
 "sending":tr(l,"Duke dërguar…","Sending…","Wird gesendet…"),
 "success":tr(l,"Kërkesa u dërgua. Faleminderit — do të të kontaktojmë në emailin e dhënë.","Your enquiry was sent. Thank you — we’ll contact you at the email you provided.","Ihre Anfrage wurde gesendet. Vielen Dank — wir melden uns unter Ihrer E-Mail-Adresse."),
 "failure":tr(l,"Dërgimi nuk u konfirmua. Teksti yt është ruajtur. Provo përsëri ose na shkruaj me email.","Sending could not be confirmed. Your text is saved. Try again or email us directly.","Der Versand konnte nicht bestätigt werden. Ihr Text bleibt erhalten. Versuchen Sie es erneut oder schreiben Sie uns direkt."),
 "invalid":tr(l,"Plotëso këtë fushë.","Please complete this field.","Bitte füllen Sie dieses Feld aus."),
 "formnote":tr(l,"Me dërgimin, të dhënat e kësaj kërkese kalojnë përmes Formspree për t’u trajtuar nga IT Department.","Submitting sends your enquiry through Formspree to IT Department.","Beim Senden wird Ihre Anfrage über Formspree an IT Department übermittelt."),
 "count":tr(l,"rezultate","results","Ergebnisse"),
 "faqgroups":tr(l,["Bashkëpunimi","Shërbimet","Procesi","Mbështetja"],["Working together","Services","Process","Support"],["Zusammenarbeit","Leistungen","Ablauf","Support"]),
 "screenshot":tr(l,"Pamje nga prezantimi i produktit","Image from the product presentation","Ansicht aus der Produktpräsentation"),
 "demo":tr(l,"Kërko një demo","Request a demo","Demo anfragen"),
 "privacy":tr(l,"Ky version nuk përdor analytics apo cookies. Drafti i formularit ruhet vetëm në këtë skedë (sessionStorage) deri kur skeda mbyllet ose kërkesa dërgohet me sukses. Kur shtyp Dërgo kërkesën, emri, emaili dhe të dhënat që plotëson dërgohen përmes Formspree te IT Department. Një dështim i lidhjes mund të mos e konfirmojë dërgimin; kontakto me email nëse nuk je i sigurt. Calendly, WhatsApp dhe Formspree kanë politikat e tyre. Mos dërgo fjalëkalime ose të dhëna të ndjeshme. Për pyetje: info@itdks.tech.","This version uses no analytics or cookies. Form drafts stay in this tab (sessionStorage) until the tab closes or the enquiry is successfully sent. When you select Send enquiry, your name, email and entered details are sent through Formspree to IT Department. A connection failure may leave delivery unconfirmed; email us if you are unsure. Calendly, WhatsApp and Formspree have their own policies. Do not submit passwords or sensitive information. Questions: info@itdks.tech.","Diese Version verwendet keine Analyse oder Cookies. Formularentwürfe bleiben in diesem Tab (sessionStorage), bis er geschlossen oder die Anfrage erfolgreich gesendet wird. Wenn Sie Anfrage senden wählen, werden Name, E-Mail und Ihre Angaben über Formspree an IT Department übermittelt. Bei Verbindungsfehlern kann der Versand unbestätigt bleiben; schreiben Sie uns im Zweifelsfall per E-Mail. Calendly, WhatsApp und Formspree haben eigene Richtlinien. Senden Sie keine Passwörter oder sensiblen Daten. Fragen: info@itdks.tech.")}

def icon(kind=0):
 paths=['<rect x="3" y="4" width="18" height="15" rx="2"/><path d="M3 9h18M8 4v5m1 5-2 2 2 2m6-4 2 2-2 2"/>','<path d="m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6Z"/><path d="m8 12 3 3 5-6"/>','<rect x="4" y="7" width="16" height="13" rx="4"/><path d="M12 3v4M2 12h2m16 0h2M8 12v2m8-2v2m-7 3h6"/>','<path d="m15 3 6 6-12 12H3v-6Z M12 6l6 6M3 15l6 6"/>']
 return '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[kind%4]+'</svg>'
def button(text,href,extra="",style=""): return f'<a class="button {style}" href="{esc(href)}" {extra}>{esc(text)}{A}</a>'
def heading(kicker,title,desc="",action=""):
 return f'<div class="section-heading"><div><p class="eyebrow">{esc(kicker)}</p><h2>{esc(title)}</h2>{f"<p>{esc(desc)}</p>" if desc else ""}</div>{action}</div>'
def intro(title,desc,t,kicker="IT DEPARTMENT"):
 return f'<section class="page-intro wrap"><p class="eyebrow">{esc(kicker)}</p><h1>{esc(title)}</h1>{f"<p class=lead>{esc(desc)}</p>" if desc else ""}</section>'
def header(page,l,t):
 nav=''.join(f'<a href="{route(p,l)}" '+('aria-current="page"' if p==page else '')+f'>{esc(label)}</a>' for p,label in [(key,dict(zip(PAGES,labels(l)))[key]) for key in NAV_ORDER])
 langs=''.join(f'<a href="{route(page,x)}" lang="{x}" aria-label="{name}" '+('aria-current="true"' if x==l else '')+f'>{x.upper()}</a>' for x,name in [("sq","Shqip"),("en","English"),("de","Deutsch")])
 variant={"creative":"creative","ai-agents":"ai"}.get(page,"original")
 return f'''<a class="skip" href="#main">{t['skip']}</a><header class="header"><div class="header-inner wrap"><a class="brand" href="{route('index',l)}" aria-label="IT Department"><img src="assets/brand/logo-{variant}.png" width="480" height="232" alt="IT Department"></a><button class="menu-toggle" aria-expanded="false" aria-controls="main-nav" aria-label="{t['menu']}"><span></span><span></span><span></span></button><nav id="main-nav" aria-label="{t['menu']}"><div class="nav-links">{nav}</div><div class="languages" aria-label="{t['lang']}">{langs}</div><a class="button nav-cta" href="{route('contact',l)}">{t['talk']}{A}</a></nav></div></header>'''
def footer(l,t,page='index'):
 links=''.join(f'<a href="{route(p,l)}">{esc(label)}</a>' for p,label in [(key,dict(zip(PAGES,labels(l)))[key]) for key in NAV_ORDER])
 social=[('Instagram','https://www.instagram.com/it.department_'),('LinkedIn','https://www.linkedin.com/company/itdks/'),('Facebook','https://www.facebook.com/share/1QrocF1oGy/?mibextid=wwXIfr')]
 variant={'creative':'creative','ai-agents':'ai'}.get(page,'original')
 return f'''<footer class="footer"><div class="wrap"><div class="footer-top"><a class="brand" href="{route('index',l)}"><img src="assets/brand/logo-{variant}.png" width="480" height="232" alt="IT Department"></a><p>{t['footer']}</p><a class="footer-email" href="mailto:{cfg['email']}">{cfg['email']}{A}</a></div><nav class="footer-nav">{links}</nav><div class="footer-bottom"><span>© 2026 IT Department · {t['location']}</span><div>{''.join(f'<a href="{url}" target="_blank" rel="noopener noreferrer">{name}{A}</a>' for name,url in social)}</div><div><a href="{route('privacy',l)}">{t['privacy']}</a><a href="{route('terms',l)}">{t['terms']}</a></div></div></div></footer>'''
def ending(l,t):
 return f'<section class="wrap end-section"><div class="end-card"><div><p class="eyebrow">{t["talk"]}</p><h2>{copy(l)["contact"]}</h2><p>{t["endingbody"]}</p></div><div class="actions">{button(t["contact"],route("contact",l))}{button("WhatsApp",wa(l),style="outline")}</div></div></section>'
def wa(l): return 'https://wa.me/'+cfg['phoneDigits']+'?text='+quote(tr(l,'Përshëndetje IT Department, dëshiroj të flasim për një projekt.','Hello IT Department, I would like to discuss a project.','Hallo IT Department, ich möchte ein Projekt besprechen.'))
def filters(group,items,l):
 return '<div class="filters" data-filter-group="'+group+'" aria-label="'+esc(tr(l,'Filtro përmbajtjen','Filter content','Inhalte filtern'))+'">'+''.join(f'<button type="button" data-filter="{key}" aria-pressed="{str(i==0).lower()}">{esc(label)}</button>' for i,(key,label) in enumerate(items))+'</div><p class="sr-only filter-status" aria-live="polite" data-filter-status="'+group+'"></p>'
def steps(l,t,names=None):
 c=copy(l); names=names or c['stepnames']
 return '<div class="steps">'+''.join(f'<article><span>0{i+1}</span><h3>{esc(name)}</h3><p>{esc(c["stepdesc"][i]) if i<len(c["stepdesc"]) else ""}</p></article>' for i,name in enumerate(names))+'</div>'
def process(l,t): return '<section class="wrap section">'+heading(t['process'],t['processHeading'])+steps(l,t)+'</section>'
def families(l,t):
 c=copy(l); c['familydesc']=tr(l,['Prezencë dhe procese.','Sisteme që mbajnë.','Rutina më të lehta.','Markë e qartë.'],['Presence and processes.','Systems you rely on.','Lighter routines.','A clearer brand.'],['Auftritt und Abläufe.','Systeme, die tragen.','Leichtere Routinen.','Eine klare Marke.']); dest=[route('services',l)+'#web',route('services',l)+'#it',route('ai-agents',l),route('creative',l)]
 return '<div class="family-grid">'+''.join(f'<a class="family-card card" href="{dest[i]}">{icon(i)}<h3>{esc(name)}</h3><p>{c["familydesc"][i]}</p><span class="card-arrow" aria-hidden="true">↗</span></a>' for i,name in enumerate(c['families']))+'</div>'
def pricing(l,t):
 cards=''
 for i,n in enumerate(source('index',l).find('article','pricing-card')):
  name=first(n,'p','kicker'); price=[99,299,779][i]
  cards+=f'<article class="price-card card"><p class="eyebrow">{esc(name)}</p><h3>{esc(first(n,"h3"))}</h3><p class="price">€{price}<span>{t["month"]}</span></p><details><summary>{t["more"]}<span aria-hidden="true">+</span></summary><ul>'+''.join(f'<li>{esc(li.text())}</li>' for li in n.find('li'))+f'</ul></details>{button(t["enquire"],route("contact",l)+"?service="+quote(name+" €"+str(price)),style="outline")}</article>'
 return '<section class="wrap section" id="packages">'+heading('IT SUPPORT',t['packages'],t['packagenote'])+'<div class="grid three">'+cards+'</div></section>'
def visual_case(l,t,featured=False):
 c=copy(l)
 return f'<article class="case-card {"featured" if featured else ""}" data-filter-item="projects" data-category="software ai"><div class="case-copy"><p class="eyebrow">{c["casebadge"]}</p><h3>{c["casetitle"]}</h3><p>{tr(l,"Nga kërkesa dhe dokumentet te aprovimi — në një rrjedhë të vetme.","From requests and documents to approval — in one connected flow.","Von Anfragen und Dokumenten zur Freigabe — in einem Ablauf.")}</p><a class="text-link" href="{route("project-detail",l)}">{c["details"]}{A}</a></div><div class="workflow-art" aria-label="{esc(c["casebadge"])}"><div class="mock-bar"><i></i><i></i><i></i><span>WORKFLOW</span></div><div class="flow-columns">'+''.join(f'<div><span>{esc(label)}</span><b></b><b></b><b></b></div>' for label in tr(l,['Kërkesa','Në punë','Aprovimi'],['Requests','In progress','Approval'],['Anfragen','In Arbeit','Freigabe']))+'</div><div class="mock-bottom"><span></span><span></span><span></span></div></div></article>'
def brandbook(key,l,t):
 name=key.upper()
 return f'<a class="brandbook card" href="assets/creative/{key}-brandbook.webp" data-lightbox="{name}" data-filter-item="projects" data-category="creative"><div class="book-image {key}"><img src="assets/creative/{key}-brandbook.webp" width="1024" height="1536" loading="lazy" alt="{name} — {t["concept"]}"><span class="image-arrow" aria-hidden="true">↗</span></div><div class="book-caption"><div><p class="eyebrow">{t["concept"]}</p><h3>{name}</h3></div>{A}</div></a>'
def home(l,t):
 c=copy(l)
 hero=f'''<section class="hero wrap"><div class="hero-copy"><p class="eyebrow"><span class="red-dot"></span>WEB / SOFTWARE / AI / IT</p><h1>{c['home']}</h1><p class="lead">{c['homelead']}</p><div class="actions">{button(c['see'],route('services',l))}{button(c['book'],cfg['bookingUrl'],'target="_blank" rel="noopener noreferrer"','dark')}</div><div class="hero-proof"><div><strong>140<span>+</span></strong><span>{tr(l,'projekte','projects','Projekte')}</span></div><div><strong>40<span>+</span></strong><span>{tr(l,'klientë','clients','Kunden')}</span></div><p>{t['location']}<br>{t['eyebrow']}</p></div></div><div class="hero-art"><p class="eyebrow">IT DEPARTMENT</p><h2>{c['flow']}</h2><div class="hero-flow">{''.join(f'<div><span>0{i+1}</span><strong>{name}</strong></div>' for i,name in enumerate(c['flowsteps']))}</div><p class="art-foot">{tr(l,'Një ekip. Nga ideja te mbështetja.','One team. From idea to ongoing support.','Ein Team. Von der Idee bis zur Betreuung.')}</p></div></section>'''
 return hero+f'<section class="wrap pillars">{families(l,t)}</section><section class="wrap section">'+heading(t['work'],c['selected'],action=f'<a class="text-link" href="{route("projects",l)}">{t["allwork"]}{A}</a>')+'<div class="selected-grid">'+visual_case(l,t,True)+brandbook('nexus',l,t)+'</div></section>'+partner_rows(l,t,True)+pricing(l,t)+ending(l,t)
def services(l,t):
 c=copy(l); nodes=source('services',l).find('article','service-card'); blocks=''
 for i,(cat,idx) in enumerate([('web',[0,1,2]),('it',[3,4,5]),('ai',[]),('creative',[6,7])]):
  items=''.join(detail(nodes[j],j+1,l,t) for j in idx)
  if cat in ['ai','creative']: items+=button(c['details'],route('ai-agents' if cat=='ai' else 'creative',l),style='outline')
  blocks+=f'<article class="service-family card" id="{cat}" data-filter-item="services" data-category="{cat}"><div class="service-family-title">{icon(i)}<span class="eyebrow">{["01 / 03","04 / 06","AI","07 / 08"][i]}</span><h2>{c["families"][i]}</h2><p>{c["familydesc"][i]}</p></div><div>{items}</div></article>'
 return intro(c['services'],t['servicelead'],t,labels(l)[1])+'<section class="wrap">'+filters('services',[('all',c['all'])]+list(zip(['web','it','ai','creative'],c['families'])),l)+'<div class="grid two service-families">'+blocks+'</div></section>'+pricing(l,t)+process(l,t)+ending(l,t)
def projects(l,t):
 c=copy(l); names=tr(l,['Web','Softuer','IT & siguri','AI','Kreativa'],['Web','Software','IT & security','AI','Creative'],['Web','Software','IT & Sicherheit','KI','Kreativ']); items=visual_case(l,t,True)
 for i,n in enumerate(source('projects',l).find('article','service-card')):
  category=['it','software','it','ai'][i]; title=first(n,'h3'); body=''.join(f'<p>{esc(p)}</p>' for p in paragraphs(n))
  items+=f'<article class="project-tile card" data-filter-item="projects" data-category="{category}"><div class="project-diagram diagram-{i}" aria-hidden="true">{icon(i)}<span></span><span></span><span></span></div><div class="project-content"><p class="eyebrow">{t["examples"]}</p><h3>{esc(title)}</h3><details><summary>{c["details"]}<span aria-hidden="true">+</span></summary>{body}<ul>'+''.join(f'<li>{esc(li.text())}</li>' for li in n.find('li'))+f'</ul>{button(c["request"],route("contact",l)+"?service="+quote(title),style="outline")}</details></div></article>'
 items+=f'<article class="project-tile card" data-filter-item="projects" data-category="web"><div class="web-art" aria-hidden="true"><div></div><strong>WEB.</strong><span></span><span></span></div><div class="project-content"><p class="eyebrow">{t["examples"]}</p><h3>{tr(l,"Nga vizitori te kërkesa.","From visitor to enquiry.","Vom Besuch zur Anfrage.")}</h3><p>{tr(l,"Një shembull strukture: ofertë e qartë, prova vizuale dhe kontakt pa pengesa.","An example structure: a clear offer, visual evidence and an easy next step.","Eine Beispielstruktur: klares Angebot, sichtbare Arbeit und ein einfacher Kontakt.")}</p><a class="text-link" href="{route("services",l)}#web">{c["see"]}{A}</a></div></article>'
 items+=brandbook('nexus',l,t)+brandbook('hyperlink',l,t)
 chips=['Web','Web App','Windows','Android','iOS','Dashboard','AI','E-commerce','Booking','CRM','POS','Inventory','API','Portal']
 return intro(c['projects'],t['projectsLead'],t,labels(l)[2])+'<section class="wrap">'+filters('projects',[('all',c['all'])]+list(zip(['web','software','it','ai','creative'],names)),l)+f'<p class="section-note">{t["examplesNote"]}</p><div class="projects-grid">{items}</div></section><section class="wrap section">'+heading(tr(l,'KAPACITETET','CAPABILITIES','MÖGLICHKEITEN'),tr(l,'Forma e duhur për punën tënde.','The right shape for your work.','Die passende Form für Ihre Arbeit.'))+'<div class="chips">'+''.join(f'<a href="{route("contact",l)}?service={quote(x)}">{x}{A}</a>' for x in chips)+'</div></section>'+ending(l,t)
def case_detail(l,t):
 c=copy(l)
 parts=tr(l,[('Nevoja','Kërkesat, dokumentet dhe aprovimet janë të shpërndara. Ekipi humb kohë duke kërkuar statusin.'),('Zgjidhja','Një rrjedhë me përgjegjës, dokumente dhe hapa aprovimi të lidhur në një vend.'),('Rezultati i synuar','Status i dukshëm dhe përgjegjësi më e qartë për çdo kërkesë.')],[('The need','Requests, documents and approvals are scattered. The team spends time searching for the status.'),('The solution','One workflow connects owners, documents and approval steps.'),('Intended result','Visible status and clearer responsibility for each request.')],[('Der Bedarf','Anfragen, Dokumente und Freigaben sind verstreut. Das Team muss den aktuellen Stand suchen.'),('Die Lösung','Ein Ablauf verbindet Verantwortliche, Dokumente und Freigabeschritte.'),('Angestrebtes Ergebnis','Sichtbarer Status und klare Verantwortung für jede Anfrage.')])
 return intro(c['casefull'],t['examplesNote'],t,c['casebadge'])+'<section class="wrap">'+visual_case(l,t,True)+'</section><section class="wrap section grid three">'+''.join(f'<article class="card padded"><p class="eyebrow">0{i+1}</p><h2>{a}</h2><p>{b}</p></article>' for i,(a,b) in enumerate(parts))+'</section><section class="wrap section"><div class="before-after"><div><p class="eyebrow">'+tr(l,'PARA · SHEMBULL','BEFORE · EXAMPLE','VORHER · BEISPIEL')+'</p><h2>'+tr(l,'Pjesë të shpërndara.','Scattered pieces.','Verteilte Einzelteile.')+'</h2><p>Email → Dokument → Telefon → Email</p></div><div><p class="eyebrow">'+tr(l,'PAS · RRJEDHË E PROPOZUAR','AFTER · PROPOSED FLOW','NACHHER · VORGESCHLAGENER ABLAUF')+'</p><h2>'+tr(l,'Një rrugë e dukshme.','One visible path.','Ein sichtbarer Weg.')+'</h2><p>'+tr(l,'Kërkesë → Përgjegjës → Aprovim → Raport','Request → Owner → Approval → Report','Anfrage → Zuständigkeit → Freigabe → Bericht')+'</p></div></div></section>'+ending(l,t)
