def partner_rows(l,t,teaser=False):
 c=copy(l); rows=''; groups=tr(l,['Rrjet & hosting','Integrime & pagesa','Mjete & ekosistem'],['Networks & hosting','Integrations & payments','Tools & ecosystem'],['Netzwerk & Hosting','Integrationen & Zahlungen','Werkzeuge & Ökosystem'])
 for i,g in enumerate(groups):
  logos=''.join(f'<a class="partner-logo" href="{route("partners",l) if teaser else ""}#partner-{key}" aria-label="{name}"><img src="assets/partners/{key}.svg" alt="{name}" loading="lazy"></a>' for key,name,group in PARTNERS if group==i)
  rows+=f'<div class="partner-row"><p>{g}</p><div>{logos}</div></div>'
 return '<section class="wrap section partner-section">'+(heading(labels(l)[3],tr(l,'Një ekosistem. Më shumë mundësi.','One ecosystem. More possibilities.','Ein Ökosystem. Mehr Möglichkeiten.'),action=f'<a class="text-link" href="{route("partners",l)}">{c["details"]}{A}</a>') if teaser else '')+rows+'</section>'
def partners(l,t):
 c=copy(l)
 descriptions=tr(l,[('Rrjet që mbështet punën e përditshme.','Planifikim dhe konfigurim rrjeti sipas pajisjeve dhe kërkesave të ekipit.'),('Lidhje me më shumë kontroll.','Rrugëzim, segmentim dhe konfigurim për nevojat e rrjetit.'),('Një bazë për faqen tënde.','Hosting, domain dhe publikim sipas kërkesave të projektit.'),('Infrastrukturë në funksion të biznesit.','Përzgjedhje dhe koordinim i infrastrukturës sipas projektit.'),('Sisteme që mund të komunikojnë.','Vlerësim i mundësive të lidhjes dhe integrimit për procesin tënd.'),('Pagesa si pjesë e rrjedhës.','Planifikim i integrimit të pagesave, sipas llogarisë dhe shërbimeve të miratuara.'),('Nga porosia te pagesa.','Vlerësim i mundësive bankare të pagesës për projektin.'),('Mjete për ide që marrin formë.','Dizajn, përmbajtje dhe materiale kreative në një rrjedhë të qëndrueshme.'),('Teknologji në një ekosistem më të gjerë.','Pajisje dhe zgjidhje të përzgjedhura sipas nevojës konkrete.')],[('A network that supports daily work.','Network planning and configuration around your equipment and team.'),('More control over your connections.','Routing, segmentation and configuration for your network needs.'),('A foundation for your website.','Hosting, domains and publishing around project requirements.'),('Infrastructure for your business.','Infrastructure selection and coordination based on the project.'),('Systems that can communicate.','Assessing connectivity and integration options for your processes.'),('Payments within the workflow.','Planning payment integration around your account and approved services.'),('From order to payment.','Assessing bank payment options for the project.'),('Tools that bring ideas to life.','Design, content and creative assets in a consistent workflow.'),('Technology in a wider ecosystem.','Equipment and solutions selected around specific needs.')],[('Ein Netzwerk für den Arbeitsalltag.','Netzwerkplanung und Konfiguration passend zu Geräten und Team.'),('Verbindungen mit mehr Kontrolle.','Routing, Segmentierung und Konfiguration für Ihren Bedarf.'),('Eine Basis für Ihre Website.','Hosting, Domains und Veröffentlichung passend zum Projekt.'),('Infrastruktur für Ihr Unternehmen.','Auswahl und Koordination der Infrastruktur nach Projektbedarf.'),('Systeme, die kommunizieren können.','Prüfung der Verbindungs- und Integrationsmöglichkeiten für Ihre Abläufe.'),('Zahlungen als Teil des Ablaufs.','Planung der Zahlungsintegration nach Konto und freigegebenen Diensten.'),('Von der Bestellung zur Zahlung.','Prüfung der Bank-Zahlungsmöglichkeiten für Ihr Projekt.'),('Werkzeuge für greifbare Ideen.','Design, Inhalte und Kreativmaterial in einem einheitlichen Ablauf.'),('Technologie im größeren Ökosystem.','Geräte und Lösungen nach konkretem Bedarf.')])
 profiles=''
 for i,(key,name,g) in enumerate(PARTNERS):
  title,desc=descriptions[i]; service=['it','web','creative'][g]
