 return hero+'<section class="wrap section" id="portfolio">'+portfolio+'</section><section class="wrap section">'+heading(labels(l)[4],tr(l,'Nga ideja te materiali i gatshëm.','From the idea to the finished work.','Von der Idee zum fertigen Material.'))+'<div class="grid three">'+offerings+'</div></section><section class="wrap section"><div class="creative-process">'+''.join(f'<div><span>0{i+1}</span><h3>{x}</h3></div>' for i,x in enumerate(flow))+'</div></section><section class="wrap bridge-card"><h2>'+tr(l,'Një gjuhë. Në çdo pikë kontakti.','One language. Every touchpoint.','Eine Sprache. An jedem Kontaktpunkt.')+'</h2><p>'+tr(l,'Identiteti lidhet me faqen, sistemin dhe fushatën. Kështu, marka jote ndihet e njëjtë kudo.','Your identity connects with the website, system and campaign. Your brand feels consistent everywhere.','Ihre Identität verbindet Website, System und Kampagne. So wirkt Ihre Marke überall einheitlich.')+'</p>'+button(c['see'],route('services',l)+'#creative',style='outline')+'</section>'+brief(l,t,'creative',tr(l,'Na trego idenë.','Tell us your idea.','Erzählen Sie uns Ihre Idee.'),tr(l,'Një brief i shkurtër është një fillim i mirë.','A short brief is a good place to start.','Ein kurzes Briefing ist ein guter Anfang.'))
